+  { time_tag: '2026-07-30T09:00:00', Kp: 2, a_running: 6, station_count: 8 },
+  { time_tag: '2026-07-30T12:00:00', Kp: 1.67, a_running: 6, station_count: 8 },
+  { time_tag: '2026-07-30T21:00:00', Kp: 1, a_running: 4, station_count: 8 },
