+  // Kp-based rolling alert
+  if (data.kpIndex !== null && data.kpIndex >= 5) {
+    const sev: AlertSeverity = data.kpIndex >= 7 ? 'critical' : (data.kpIndex >= 6 ? 'high' : 'medium');
