     1	/**
     2	 * Call-site regression tests for fetchSpaceWeather().
     3	 *
     4	 * space-weather-parse.test.mts proves the PARSERS handle the real SWPC shapes.
     5	 * That is not the bug that emptied the panel: the parsers were being handed the
     6	 * wrong thing. fetchSpaceWeather() issued five identical requests to
     7	 * /api/space-weather-feeds and gated each parse on Array.isArray() of the
     8	 * response — but the route answers with one OBJECT keyed by product, so every
     9	 * branch was skipped and every field stayed null while the fetch itself
    10	 * "succeeded".
    11	 *
    12	 * Parser-only coverage cannot see that regression come back, so these tests
    13	 * drive the exported function with a stubbed fetch instead.
    14	 *
    15	 * The module holds a private TTL cache with no reset seam. Rather than depend on
    16	 * declaration order — which made these tests fail when run individually — each
    17	 * one advances a stubbed clock far enough to expire whatever a previous test
    18	 * left behind, so every test is self-contained and the TTLs themselves become
    19	 * observable.
    20	 */
    21	import { strict as assert } from 'node:assert';
    22	import test from 'node:test';
    23	
    24	import { fetchSpaceWeather } from '@/services/space-weather';
    25	
    26	const REAL_NOW = Date.now.bind(Date);
    27	let clockOffsetMs = 0;
    28	Date.now = () => REAL_NOW() + clockOffsetMs;
    29	
    30	const COMPLETE_TTL_MS = 5 * 60 * 1000;
    31	const PARTIAL_TTL_MS = 60 * 1000;
    32	
    33	/** Jump past the longest cache lifetime, so the next call is guaranteed to fetch. */
    34	function expireEverything(): void {
    35	  clockOffsetMs += COMPLETE_TTL_MS + 1000;
    36	}
    37	
    38	/**
    39	 * SWPC's naïve-UTC stamp format ("2026-07-30 19:03:19.350") for an instant
    40	 * `minutesAgo` in the past. parseAlerts windows against the REAL clock, so a
    41	 * hard-coded date would age out of the 24-hour window and make this suite start
    42	 * failing on a date unrelated to any code change.
    43	 */
    44	function issuedMinutesAgo(minutesAgo: number): string {
    45	  return new Date(REAL_NOW() - minutesAgo * 60_000)
    46	    .toISOString()
    47	    .replace('T', ' ')
    48	    .replace('Z', '');
    49	}
    50	
    51	const ALERT_ISSUED_AT = issuedMinutesAgo(60);
    52	
    53	/** The real envelope shape: one object keyed by SWPC product. */
    54	const FEEDS = {
    55	  kp: [
    56	    { time_tag: '2026-07-30T18:00:00', Kp: 3, a_running: 7, station_count: 8 },
    57	    { time_tag: '2026-07-30T21:00:00', Kp: 6, a_running: 9, station_count: 8 },
    58	  ],
    59	  wind: [
    60	    ['time_tag', 'speed', 'density', 'bz'],
    61	    ['2026-07-30 20:55:00.000', '512.4', '6.1', '-8.3'],
    62	  ],
    63	  xray: [{ max_class: 'M2.4', current_class: 'C1.1' }],
    64	  alerts: [
    65	    {
    66	      product_id: 'ALTK07',
    67	      issue_datetime: ALERT_ISSUED_AT,
    68	      message: 'Space Weather Message Code: ALTK07\r\nSerial Number: 366\r\n\r\nALERT: Geomagnetic K-index of 7\r\n',
    69	    },
    70	  ],
    71	};
    72	
    73	let requests: string[] = [];
    74	
    75	/** Installs a fetch stub returning `body`, and records every URL requested. */
    76	function stubFetch(body: unknown, ok = true) {
    77	  requests = [];
    78	  const original = globalThis.fetch;
    79	  globalThis.fetch = (async (url: string | URL | Request) => {
    80	    requests.push(typeof url === 'string' ? url : String((url as URL).href ?? url));
    81	    return {
    82	      ok,
    83	      status: ok ? 200 : 502,
    84	      json: async () => body,
    85	    } as Response;
    86	  }) as typeof globalThis.fetch;
    87	  return () => { globalThis.fetch = original; };
    88	}
